package wgmodern;
import java.util.*;import net.minecraft.core.*;import net.minecraft.server.level.ServerLevel;import net.minecraft.util.RandomSource;import net.minecraft.world.*;import net.minecraft.world.entity.*;import net.minecraft.world.entity.player.Player;import net.minecraft.world.item.*;import net.minecraft.world.item.context.*;import net.minecraft.world.level.*;import net.minecraft.world.level.block.*;import net.minecraft.world.level.block.state.*;import net.minecraft.world.level.block.state.properties.*;import net.minecraft.world.phys.shapes.*;import net.minecraftforge.common.IForgeShearable;import tc4revival.content.WandInteractable;
public class RoseVines extends Block implements IForgeShearable,WandInteractable {
 public static final IntegerProperty AGE=IntegerProperty.create("age",0,5);public static final Map<Direction,BooleanProperty> FACES=new LinkedHashMap<>();static{for(var d:List.of(Direction.DOWN,Direction.NORTH,Direction.SOUTH,Direction.WEST,Direction.EAST))FACES.put(d,BooleanProperty.create(d.getName()));}
 public RoseVines(){super(Properties.copy(Blocks.VINE).noCollission().noOcclusion().randomTicks());var s=stateDefinition.any().setValue(AGE,0);for(var p:FACES.values())s=s.setValue(p,false);registerDefaultState(s);}
 @Override protected void createBlockStateDefinition(StateDefinition.Builder<Block,BlockState> b){b.add(AGE);for(var p:FACES.values())b.add(p);}
 public static boolean supported(BlockGetter l,BlockPos p,Direction d){var neighbor=p.relative(d);return l.getBlockState(neighbor).isFaceSturdy(l,neighbor,d.getOpposite());}
 public BlockState attachments(LevelReader l,BlockPos p,BlockState s){for(var entry:FACES.entrySet())s=s.setValue(entry.getValue(),supported(l,p,entry.getKey()));return s;}
 @Override public BlockState getStateForPlacement(BlockPlaceContext c){return attachments(c.getLevel(),c.getClickedPos(),defaultBlockState());}
 @Override public BlockState updateShape(BlockState s,Direction d,BlockState neighbor,LevelAccessor l,BlockPos p,BlockPos np){return attachments(l,p,s);}
 @Override public void randomTick(BlockState s,ServerLevel l,BlockPos p,RandomSource random){grow(l,p,random,false);}
 public void grow(Level l,BlockPos p,RandomSource random,boolean force){var s=l.getBlockState(p);if(!s.is(this))return;if(s.getValue(AGE)<5){l.setBlock(p,s.setValue(AGE,s.getValue(AGE)+1),2);return;}var target=p.above();if(l.hasChunkAt(target)&&l.isEmptyBlock(target)&&(force||random.nextInt(4)==0)){var state=attachments(l,target,defaultBlockState());if(List.of(Direction.NORTH,Direction.SOUTH,Direction.WEST,Direction.EAST).stream().anyMatch(d->state.getValue(FACES.get(d))))l.setBlockAndUpdate(target,state);}}
 @Override public void entityInside(BlockState s,Level l,BlockPos p,Entity e){if(e instanceof LivingEntity)e.hurt(l.damageSources().generic(),1);}
 @Override public VoxelShape getShape(BlockState s,BlockGetter l,BlockPos p,CollisionContext c){VoxelShape shape=Shapes.empty();if(s.getValue(FACES.get(Direction.DOWN)))shape=Block.box(0,0,0,16,6,16);if(s.getValue(FACES.get(Direction.NORTH)))shape=Shapes.or(shape,Block.box(0,0,0,16,16,4));if(s.getValue(FACES.get(Direction.SOUTH)))shape=Shapes.or(shape,Block.box(0,0,12,16,16,16));if(s.getValue(FACES.get(Direction.WEST)))shape=Shapes.or(shape,Block.box(0,0,0,4,16,16));if(s.getValue(FACES.get(Direction.EAST)))shape=Shapes.or(shape,Block.box(12,0,0,16,16,16));return shape.isEmpty()?Shapes.block():shape;}
 @Override public boolean isShearable(ItemStack item,Level world,BlockPos pos){return true;}
 @Override public List<ItemStack> onSheared(Player p,ItemStack item,Level world,BlockPos pos,int fortune){return List.of(new ItemStack(this));}
 @Override public InteractionResult onWandUseFirst(ItemStack w,UseOnContext c){if(c.getPlayer()!=null&&c.getPlayer().isCreative()&&!c.getLevel().isClientSide)grow(c.getLevel(),c.getClickedPos(),c.getLevel().random,true);return InteractionResult.sidedSuccess(c.getLevel().isClientSide);}
 @Override public Optional<ItemStack> onWandUse(Level l,ItemStack w,Player p){return Optional.empty();}@Override public void onWandUseTick(ItemStack w,Player p,int ticks){}@Override public void onWandRelease(ItemStack w,Level l,Player p,int ticks){}
}
